replacements.after:
/* v2.9.113 · Main Character Banner shell. Scene ownership is per sidebar menu. */
#app .ds-main-character-banner{--mcb-accent:#f0bd66;--mcb-ink:#fff;--mcb-muted:#d8e0ef;--mcb-bg:#0d1729;--mcb-border:#ffffff24;--mcb-overlay:linear-gradient(90deg,#081325 0%,#0a1625f5 37%,#0a1625a8 58%,transparent 86%);--mcb-overlay-mobile:linear-gradient(90deg,#081325f7 0%,#0a1625e8 56%,#0a16259c 100%);--mcb-status-bg:#07111da6;--mcb-status-line:#ffffff38;--mcb-scene-position:76% 48%;--mcb-scene-width:auto;--mcb-scene-fit:cover;--mcb-scene-mask:linear-gradient(90deg,transparent 0%,#000 17%,#000 100%);position:relative;isolation:isolate;display:grid;grid-template-columns:minmax(0,54%) minmax(0,46%);align-items:stretch;width:100%;height:auto;min-height:232px;box-sizing:border-box;margin:0 0 14px;border:1px solid var(--mcb-border);border-radius:22px;overflow:hidden;background:var(--mcb-bg);box-shadow:var(--ds-shadow)}
#app .ds-main-character-banner:after{content:"";position:absolute;z-index:1;inset:0;background:var(--mcb-overlay);pointer-events:none}

#app .ds-main-character-banner--duo-or-trio{--mcb-scene-position:74% 38%}
#app .ds-main-character-banner--group{--mcb-scene-position:right center;--mcb-scene-width:auto;--mcb-scene-fit:cover}
#app .ds-main-character-banner.ds-tone-sports{--mcb-accent:#f5c26b;--mcb-bg:#0b1425}
#app .ds-main-character-banner__scene{position:absolute;z-index:0;inset:0;margin:0;overflow:hidden;pointer-events:none}
/* 3:1 scenes keep their full frame on wide desktop banners; the overlay stays on the copy side. */
@media(min-width:701px){#app :not(#home)>.ds-main-character-banner:after{background-size:64% 100%;background-repeat:no-repeat}}
#app .ds-main-character-banner__scene img{display:block;width:var(--mcb-scene-width);max-width:100%;height:100%;margin-left:auto;object-fit:var(--mcb-scene-fit);object-position:var(--mcb-scene-position);-webkit-mask-image:var(--mcb-scene-mask);mask-image:var(--mcb-scene-mask)}
#app .ds-main-character-banner__copy{position:relative;z-index:2;grid-column:1;display:flex;flex-direction:column;justify-content:center;align-items:flex-start;min-width:0;padding:16px 26px;color:var(--mcb-ink)}
